// Fan effectiveness index — record JAH-GPC-CASEFAN-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cfm": 60, "static_pressure": 1.5, "noise_db": 28};
var value = (m.cfm*m.static_pressure/m.noise_db);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-CASEFAN-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-CASEFAN-000001|' + value.toFixed(2) + ' effectiveness index');

